#!/usr/bin/env python3
import sys


def to_base36(n: int, width: int) -> str:
    """Encode integer n as a zero-padded base36 string of given width."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(width):
        result.append(chars[n % 36])
        n //= 36
    # Built reversed, so flip
    return "".join(reversed(result))


def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    # Last non-empty line is the most recent id
    last_line = lines[-1]
    # Expect format: "N\tORD-XXXX"
    parts = last_line.split("\t")
    if len(parts) < 2:
        print(f"Unexpected format: {last_line!r}", file=sys.stderr)
        sys.exit(1)

    last_id = parts[-1]
    suffix = last_id.removeprefix("ORD-")

    if len(suffix) != 4:
        print(f"Unexpected id format: {last_id!r}", file=sys.stderr)
        sys.exit(1)

    try:
        current = int(suffix, 36)
    except ValueError:
        print(f"Could not parse suffix: {suffix!r}", file=sys.stderr)
        sys.exit(1)

    next_suffix = to_base36(current + 1, 4)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

