import sys
from pathlib import Path


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base-36 string of given width."""
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return "0" * width
    result = []
    while n > 0:
        result.append(digits[n % 36])
        n //= 36
    return "".join(reversed(result)).rjust(width, "0")


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def main() -> None:
    ids_file = Path("ids.txt")
    if not ids_file.exists():
        print("ORD-0000")
        return

    lines = [line.strip() for line in ids_file.read_text().splitlines() if line.strip()]
    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    suffix = last_id.replace("ORD-", "")
    next_num = base36_decode(suffix) + 1
    next_suffix = base36_encode(next_num)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

