import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def to_base36(n: int) -> str:
    """Convert an integer to a base-36 string (uppercase)."""
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))

def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n

def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_line = lines[-1]
    # Expected format: ORD-XXXX
    suffix = last_line.split("-", 1)[-1]
    try:
        num = from_base36(suffix)
        next_num = num + 1
        next_suffix = to_base36(next_num).zfill(4).upper()
        print(f"ORD-{next_suffix}")
    except (ValueError, IndexError):
        print(f"Error: could not parse last id '{last_line}'", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

