import sys

def ord_to_int(suffix: str) -> int:
    """Convert a 4-character base-36 string to an integer."""
    return int(suffix, 36)

def int_to_ord(n: int) -> str:
    """Convert an integer to a 4-character uppercase base-36 string."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(4):
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result))

def next_id(last_id: str) -> str:
    prefix = last_id[:4]  # "ORD-"
    suffix = last_id[4:]   # e.g. "243G"
    n = ord_to_int(suffix)
    return prefix + int_to_ord(n + 1)

def main():
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        print("ORD-0000")
        return
    last = lines[-1]
    print(next_id(last))

if __name__ == "__main__":
    main()

