#!/usr/bin/env python3
"""Write manifest.json with SHA-256 hex digests of every file under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_PATH = "manifest.json"


def sha256_hex(filepath: str) -> str:
    """Return the SHA-256 hex digest of *filepath*."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    for root, _dirs, files in os.walk(RELEASE_DIR):
        for name in sorted(files):
            relpath = os.path.join(root, name)
            manifest[relpath] = sha256_hex(relpath)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write("\n")

    print(f"wrote {MANIFEST_PATH} with {len(manifest)} entries")
    for path, digest in manifest.items():
        print(f"  {digest}  {path}")


if __name__ == "__main__":
    main()

