#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST = "manifest.json"


def sha256_file(path):
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main():
    manifest = {}
    for root, _dirs, files in os.walk(RELEASE_DIR):
        for name in files:
            full = os.path.join(root, name)
            relpath = os.path.relpath(full, os.getcwd())
            manifest[relpath] = sha256_file(full)

    with open(MANIFEST, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

