"""Write manifest.json: a mapping of every file under release/ to its SHA-256 digest."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_FILE = Path("manifest.json")


def sha256_hex(filepath: Path) -> str:
    return hashlib.sha256(filepath.read_bytes()).hexdigest()


def main() -> None:
    manifest = {}

    if RELEASE_DIR.is_dir():
        for fpath in sorted(RELEASE_DIR.rglob("*")):
            if fpath.is_file():
                # Store the path relative to the repository root
                key = str(fpath)
                manifest[key] = sha256_hex(fpath)

    MANIFEST_FILE.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    print(f"Wrote {len(manifest)} entries to {MANIFEST_FILE}")


if __name__ == "__main__":
