#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def sha256_hex(filepath: Path) -> str:
    """Return the SHA-256 hex digest of the file at *filepath*."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            block = f.read(65536)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} does not exist or is not a directory.")
        raise SystemExit(1)

    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if not fpath.is_file():
            continue
        rel_path = str(fpath.relative_to(REPO_ROOT))
        manifest[rel_path] = sha256_hex(fpath)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

