#!/usr/bin/env python3
"""List report files in report order (by numeric suffix)."""

import os
import re


def report_sort_key(filename: str) -> tuple[int, str]:
    """Extract the numeric portion for natural ordering."""
    match = re.search(r'report-(\d+)\.txt$', filename)
    if match:
        return (int(match.group(1)), filename)
    return (float('inf'), filename)


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'reports')
    try:
        entries = os.listdir(reports_dir)
    except FileNotFoundError:
        return

    report_files = [e for e in entries if e.startswith('report-') and e.endswith('.txt')]
    report_files.sort(key=report_sort_key)

    for fname in report_files:
        print(fname)


if __name__ == '__main__':
    main()

