#!/usr/bin/env python3
"""Print report file names in order, one per line."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")


def report_key(filename: str) -> tuple[int, str]:
    """Return a sort key for a report filename."""
    m = re.match(r"report-(\d+)\.txt", filename)
    if m:
        return (int(m.group(1)), filename)
    # Fallback for unexpected names – sort by name after all numbered ones.
    return (float("inf"), filename)


def main() -> None:
    try:
        names = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return  # No reports directory – nothing to print.
    names.sort(key=report_key)
    for name in names:
        print(name)


if __name__ == "__main__":
    main()
