#!/usr/bin/env python3
"""Print report file names under reports/, one per line, in report order."""

from pathlib import Path


def main() -> None:
    reports_dir = Path(__file__).resolve().parent / "reports"
    # Find all report-<n>.txt files, sort by the numeric part
    reports = sorted(
        reports_dir.glob("report-*.txt"),
        key=lambda p: int(p.stem.split("-")[1]),
    )
    for r in reports:
        print(r.name)


if __name__ == "__main__":
    main()

