#!/usr/bin/env python3
"""List the file names under reports/, one per line, in report (natural) order."""

import re
from pathlib import Path

REPORTS_DIR = Path(__file__).resolve().parent / "reports"


def natural_key(name: str):
    """Split a name into chunks so numbers compare numerically, not lexically."""
    return [
        (0, int(chunk), "") if chunk.isdigit() else (1, 0, chunk.lower())
        for chunk in re.split(r"(\d+)", name)
    ]


def main() -> None:
    names = sorted(
        (p.name for p in REPORTS_DIR.iterdir() if p.is_file()),
        key=natural_key,
    )
    for name in names:
        print(name)


if __name__ == "__main__":
    main()
