"""Rotate app.log: move entries older than 7 days before AS_OF to archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_ts(line: str) -> datetime | None:
    """Try to parse a leading YYYY-MM-DD HH:MM:SS timestamp from a line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.fromtimestamp(as_of - 7 * 86400, tz=timezone.utc)

    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found.", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        stripped = line.rstrip("\n")
        if not stripped:
            # Preserve empty lines if any
            keep.append(line)
            continue
        ts = parse_ts(stripped)
        if ts is None:
            # Lines without a parseable timestamp stay in app.log
            keep.append(line)
        elif ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    with open("app.log", "w") as f:
        f.writelines(keep)

    if archive:
        with open("archive.log", "a") as f:
            f.writelines(archive)


if __name__ == "__main__":
    main()

