import sys
import os
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse a 'YYYY-MM-DD HH:MM:SS' prefix from the line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of_ts = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp, got {sys.argv[1]!r}", file=sys.stderr)
        sys.exit(1)

    as_of = datetime.fromtimestamp(as_of_ts, tz=timezone.utc)
    cutoff = as_of - timedelta(days=7)

    root = os.path.dirname(os.path.abspath(__file__))
    app_log = os.path.join(root, "app.log")
    archive_log = os.path.join(root, "archive.log")

    if not os.path.exists(app_log):
        print(f"Error: {app_log} not found", file=sys.stderr)
        sys.exit(1)

    with open(app_log, "r") as f:
        lines = f.readlines()

    # Filter out trailing empty lines but keep them for rewrite
    old_entries = []
    new_entries = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None and dt < cutoff:
            old_entries.append(line)
        else:
            new_entries.append(line)

    # Append old entries to archive.log
    if old_entries:
        with open(archive_log, "a") as f:
            f.writelines(old_entries)

    # Rewrite app.log with remaining entries
    with open(app_log, "w") as f:
        f.writelines(new_entries)

    print(f"Rotated {len(old_entries)} entries to archive, {len(new_entries)} remain in app.log")


if __name__ == "__main__":
    main()

