#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone

def parse_timestamp(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' from the start of a line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - 7 * 24 * 3600  # 7 days in seconds

    with open("app.log") as f:
        lines = f.readlines()

    kept = []
    archived = []

    for line in lines:
        line = line.rstrip("\n")
        if not line:
            continue
        ts = parse_timestamp(line)
        if ts is None:
            # unparseable – keep in app.log
            kept.append(line)
        elif ts.timestamp() < cutoff:
            archived.append(line)
        else:
            kept.append(line)

    with open("app.log", "w") as f:
        f.write("\n".join(kept))
        if kept:
            f.write("\n")

    with open("archive.log", "a") as f:
        if archived:
            f.write("\n".join(archived))
            f.write("\n")

if __name__ == "__main__":
    main()

