"""Rotate entries from app.log into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every entry in app.log whose
timestamp is strictly older than 7 days before AS_OF is moved to archive.log.
Both files are kept in the repository root, with entries in chronological order.
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading YYYY-MM-DD HH:MM:SS from a log line as UTC."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 24 * 60 * 60  # 7 days in seconds
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    log_path = "app.log"
    archive_path = "archive.log"

    try:
        with open(log_path) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {log_path} not found", file=sys.stderr)
        sys.exit(1)

    keep = []
    archive = []

    for line in lines:
        # Preserve empty lines as-is (e.g. trailing newline)
        stripped = line.rstrip("\n")
        if not stripped:
            keep.append(line)
            continue

        ts = parse_timestamp(stripped)
        if ts is None:
            # Lines without a parseable timestamp are kept in app.log
            keep.append(line)
        elif ts < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    # Write archive (append mode, preserving order)
    with open(archive_path, "a") as f:
        for line in archive:
            f.write(line)

    # Rewrite app.log with remaining entries
    with open(log_path, "w") as f:
        for line in keep:
            f.write(line)


if __name__ == "__main__":
    main()

