"""Rotate entries in app.log that are strictly older than 7 days before AS_OF."""

import sys
import time
import calendar
from datetime import datetime, timezone

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"
DAYS = 7


def parse_timestamp(line: str) -> int | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a line and return a Unix timestamp."""
    if len(line) < 19:
        return None
    try:
        dt = datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
        dt = dt.replace(tzinfo=timezone.utc)
        return int(calendar.timegm(dt.timetuple()))
    except ValueError:
        return None


def main():
    if len(sys.argv) != 2:
        print(f"Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - DAYS * 24 * 3600

    try:
        with open(LOG_FILE) as f:
            lines = f.readlines()
    except FileNotFoundError:
        lines = []

    if not lines:
        # Nothing to rotate
        return

    keep = []
    archive = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Write back app.log with remaining entries (preserve trailing newline style)
    with open(LOG_FILE, "w") as f:
        f.writelines(keep)

    # Append archived entries to archive.log
    if archive:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(archive)


if __name__ == "__main__":
    main()

